  7	fn finite(values: &[f64]) -> bool {
  8	    values.iter().all(|v| v.is_finite())
  9	}
 10	fn coord(value: f64) -> bool {
 11	    value.is_finite() && value.abs() <= 1e6
 12	}
 13	fn region(values: &[f64; 4]) -> bool {
 14	    finite(values) && values.iter().all(|v| v.abs() <= 1e6) && values[2] >= 0.0 && values[3] >= 0.0
 15	}
 16	fn span(source: &[u8], value: Span) -> Result<()> {
 17	    if value.slice(source).is_none() {
 18	        Err(invalid(value.start))
 19	    } else {
 20	        Ok(())
 21	    }
 22	}
