 40	pub(crate) fn viewport(value: Viewport) -> Result<()> {
 41	    if value.width == 0
 42	        || value.height == 0
 43	        || !coord(value.view_x)
 44	        || !coord(value.view_y)
 45	        || !coord(value.view_width)
 46	        || !coord(value.view_height)
 47	        || value.view_width <= 0.0
 48	        || value.view_height <= 0.0
 49	        || !finite(&[value.aspect.align_x, value.aspect.align_y])
 50	        || !(0.0..=1.0).contains(&value.aspect.align_x)
 51	        || !(0.0..=1.0).contains(&value.aspect.align_y)
 52	    {
 53	        Err(Diagnostic {
 54	            kind: ErrorKind::Viewport,
 55	            offset: 0,
 56	        })
 57	    } else {
 58	        Ok(())
 59	    }
 60	}
 61	pub(crate) fn transform(
 62	    builder: &SceneBuilder,
 63	    id: SceneId,
 64	    value: &TransformFrame,
 65	    control: &mut dyn WorkControl,
 66	) -> Result<()> {
 67	    charge(control, WorkKind::Transform)?;
 68	    source_offset(&builder.source, value.source_offset)?;
 69	    if ![value.attribute, value.suffix, value.motion]
 70	        .into_iter()
 71	        .all(affine_valid)
 72	    {
 73	        return Err(invalid(value.source_offset));
 74	    }
 75	    if let Some(parent) = value.parent {
 76	        if builder.traversal_scene(id)?.transform(parent).is_none() {
 77	            return Err(invalid(value.source_offset));
 78	        }
 79	    }
 80	    Ok(())
 81	}
 82	pub(crate) fn stops(values: &[PaintStop], control: &mut dyn WorkControl) -> Result<()> {
 83	    let mut previous = 0.0;
 84	    for stop in values {
 85	        charge(control, WorkKind::PaintVisit)?;
 86	        if !stop.offset.is_finite() || stop.offset < previous || stop.offset > 1.0 {
 87	            return Err(invalid(0));
 88	        }
 89	        previous = stop.offset;
 90	    }
 91	    Ok(())
 92	}
