101	pub(crate) fn paint_view<V: ViewportRead, A: Copy>(
102	    scene: SceneView<'_, V, A>,
103	    value: &Paint,
104	    control: &mut dyn WorkControl,
105	) -> Result<()> {
106	    charge(control, WorkKind::PaintVisit)?;
107	    value.stops.require(scene.stops.len(), 0)?;
108	    if value.stops.count > 256 {
109	        return Err(limit(LimitKind::PaintStops));
110	    }
111	    stops(
112	        value.stops.slice(scene.stops).ok_or_else(|| invalid(0))?,
113	        control,
114	    )?;
115	    if !finite(&value.coordinates)
116	        || !region(&value.bounds)
117	        || ![
118	            value.user_inverse,
119	            value.gradient_inverse,
120	            value.pattern_inverse,
121	        ]
122	        .into_iter()
123	        .all(affine_valid)
124	        || !value.pattern_opacity.is_finite()
125	        || !(0.0..=1.0).contains(&value.pattern_opacity)
126	    {
127	        return Err(invalid(0));
128	    }
129	    if value.coordinates.iter().any(|v| v.abs() > 1e6) {
130	        return Err(invalid(0));
131	    }
132	    if value.kind == PaintKind::Radial && value.coordinates[2] < 0.0 {
133	        return Err(invalid(0));
134	    }
135	    if let Some(pattern) = value.pattern {
136	        if scene.pattern(pattern).is_none() {
137	            return Err(invalid(0));
138	        }
139	    }
140	    if value.kind == PaintKind::Pattern && value.pattern.is_none() {
141	        return Err(invalid(0));
142	    }
143	    Ok(())
144	}
