153	pub(crate) fn shape_attributes_view<V: ViewportRead, A: Copy>(
154	    scene: SceneView<'_, V, A>,
155	    value: &Shape,
156	    control: &mut dyn WorkControl,
157	) -> Result<()> {
158	    charge(control, WorkKind::TokenVisit)?;
159	    span(scene.source(), value.source.element)?;
160	    if !affine_valid(value.source.transform) || !affine_valid(value.stroke_inverse) {
161	        return Err(invalid(value.source.element.start));
162	    }
163	    if let Some(node) = value.source.transform_node {
164	        if scene.transform(node).is_none() {
165	            return Err(invalid(0));
166	        }
167	    }
168	    if let Some(clip) = value.clip {
169	        if scene.clip(clip).is_none() {
170	            return Err(invalid(0));
171	        }
172	    }
173	    for (index, length) in [
174	        (value.fill_paint, scene.fill_paints.len()),
175	        (value.stroke_paint, scene.stroke_paints.len()),
176	        (value.image, scene.images.len()),
177	    ] {
178	        if index.is_some_and(|i| i >= length) {
179	            return Err(invalid(0));
180	        }
181	    }
182	    let stroke = value.stroke;
183	    if !stroke.width.is_finite()
184	        || !(0.0..=1024.0).contains(&stroke.width)
185	        || !stroke.miter_limit.is_finite()
186	        || !(1.0..=64.0).contains(&stroke.miter_limit)
187	        || !coord(stroke.dash_offset)
188	        || stroke.paint_order > 5
189	    {
190	        return Err(invalid(0));
191	    }
192	    stroke.dash_values.require(scene.dash_values.len(), 0)?;
193	    if stroke.dash_values.count > 16 {
194	        return Err(limit(LimitKind::DashCache));
195	    }
196	    Ok(())
197	}
198	pub(crate) fn path(
199	    source: &[u8],
200	    value: &vexel_svg_path::PathDocument,
201	    source_range: Span,
202	    control: &mut dyn WorkControl,
203	) -> Result<()> {
204	    for &e in &value.edges {
205	        charge(control, WorkKind::Edge)?;
206	        edge(e)?;
207	    }
208	    let mut end = 0;
209	    let mut overlap = false;
210	    for subpath in &value.subpaths {
211	        charge(control, WorkKind::TokenVisit)?;
212	        let range = TableRange {
213	            first: subpath.first_edge,
214	            count: subpath.edge_count,
215	        };
216	        range.require(value.edges.len(), 0)?;
217	        overlap |= range.first < end;
218	        end = range.end().ok_or_else(|| invalid(0))?;
219	    }
220	    if overlap {
221	        crate::path_topology::canonical(
222	            &value.subpaths,
223	            TableRange {
224	                first: 0,
225	                count: value.edges.len(),
226	            },
227	            &value.edges,
228	            source_range,
229	            value.segments.iter().copied(),
230	            control,
231	        )?;
232	    }
233	    for segment in &value.segments {
234	        charge(control, WorkKind::TokenVisit)?;
235	        segment_valid(source, *segment, value.edges.len(), value.numbers.len())?;
236	    }
237	    for number in &value.numbers {
238	        charge(control, WorkKind::SourceRead)?;
