  8	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
  9	pub enum DecodeInitialization {
 10	    /// Root traversal has not established a viewport or hidden disposition.
 11	    Unresolved,
 12	    /// Root viewport is validated; actual same-source animation is still absent.
 13	    Traversing,
 14	    /// Root display:none skipped viewport and descendants; animation is absent.
 15	    Hidden,
 16	    /// Empty hidden document with its actual same-source animation installed.
 17	    HiddenFinalized,
 18	    Finalized,
 19	}
 20	/// Failure returns the actual input owner unchanged; callers can retry or drop it.
 21	#[derive(Debug)]
 22	pub struct FinalizationError {
 23	    pub diagnostic: Diagnostic,
 24	    pub animation: OwnedAnimation,
 25	}
 26	/// No apparently completed empty animation exists during traversal.
