 28	pub(crate) enum AnimationStorage { Pending, Parsed(OwnedAnimation) }
 29	impl AnimationStorage {
 30	    pub(crate) fn parsed(&self) -> Option<&OwnedAnimation> {
 31	        match self { Self::Pending => None, Self::Parsed(value) => Some(value) }
 32	    }
 33	    pub(crate) fn into_parsed(self) -> Option<OwnedAnimation> {
 34	        match self { Self::Pending => None, Self::Parsed(value) => Some(value) }
 35	    }
 36	    pub(crate) fn storage_bytes(&self) -> Option<usize> {
 37	        self.parsed()?.storage_bytes()
 38	    }
 39	}
 40	impl SceneBuilder {
 41	    pub fn provisional(source: SourceOwner, generation: u64, limits: Limits) -> Result<Self> {
 42	        let limits = limits.effective();
 43	        if source.len() > limits.source_bytes { return Err(limit(LimitKind::SourceBytes)); }
 44	        let live = source.capacity();
 45	        if live > limits.reserved_bytes { return Err(limit(LimitKind::ReservedBytes)); }
 46	        let owner = crate::builder::NEXT_OWNER
 47	            .try_update(Ordering::Relaxed, Ordering::Relaxed, |v| v.checked_add(1))
 48	            .map_err(|_| arithmetic())?;
 49	        let mut value = Self {
 50	            owner, source, generation, scenes: Vec::new(), animation: AnimationStorage::Pending,
 51	            initialization: DecodeInitialization::Unresolved,
 52	            ignored: [Ignored::default(); 4],
 53	            stats: MemoryStats { source_bytes: live, live_bytes: live,
 54	                peak_live_bytes: live, ..Default::default() },
 55	            limits, drafts: [None; 64], draft_depth: 0, request: None,
 56	            text_commands: 0, next_serial: 1,
 57	            root: SceneId { owner, slot: 0, serial: 1 },
 58	        };
 59	        let root = value.reserve_scene()?;
 60	        value.scenes.push(SceneData::new(root.serial, None));
 61	        value.root = root;
 62	        Ok(value)
 63	    }
 64	    pub fn initialization(&self) -> DecodeInitialization { self.initialization }
 65	    pub fn generation(&self) -> u64 { self.generation }
 66	    pub(crate) fn require_finalized(&self) -> Result<()> {
 67	        if self.initialization != DecodeInitialization::Finalized || self.animation.parsed().is_none() {
 68	            return Err(invalid(0));
 69	        }
 70	        Ok(())
 71	    }
 72	    pub fn traversal_scene(&self, id: SceneId) -> Result<TraversalView<'_>> {
 73	        let i = self.index(id)?;
 74	        Ok(self.scenes[i].view(self.owner, i, &self.scenes, &self.source,
 75	            self.animation.parsed().map(OwnedAnimation::view), self.scenes[i].viewport,
 76	            self.ignored))
 77	    }
 78	    fn root_witness(&self, source: &DecodeSource<'_>, root: ElementId,
 79	        control: &mut dyn WorkControl) -> Result<()> {
 80	        control.checkpoint().map_err(stopped)?;
 81	        if self.initialization != DecodeInitialization::Unresolved
 82	            || !std::sync::Arc::ptr_eq(&self.source, source.source_owner()) {
 83	            return Err(invalid(0));
 84	        }
 85	        let element = source.element(root, add(root.0, 1)?, control)?;
 86	        let token = &element.tokens()[root.0];
 87	        if token.depth != 0 || token.local_name.slice(&self.source) != Some(b"svg") {
 88	            return Err(invalid(token.name.offset));
 89	        }
 90	        Ok(())
 91	    }
 92	    // Guard the hidden bypass with the canonical CSS engine, including original
 93	    // invalid-display priority. This is a root query, never a second source parse.
 94	    fn root_display(&self, source: &mut DecodeSource<'_>, root: ElementId,
 95	        control: &mut dyn WorkControl) -> Result<bool> {
 96	        self.root_witness(source, root, control)?;
 97	        let style = source.compute_style(root, None, control)?;
 98	        let Some(value) = style.value(vexel_svg_css::Property::Display) else { return Ok(false) };
 99	        if style.keyword_equals(vexel_svg_css::Property::Display, b"none") { return Ok(true); }
100	        if [b"inline".as_slice(), b"block", b"contents"].iter()
101	            .any(|word| style.keyword_equals(vexel_svg_css::Property::Display, word)) {
102	            return Ok(false);
103	        }
104	        Err(Diagnostic { kind: ErrorKind::Unsupported, offset: value.span.offset })
105	    }
106	    /// Called after original root attribute/style/display/transform checks.
107	    /// No viewport parser is supplied here; the decoder owns that algorithm.
108	    pub fn initialize_root(&mut self, source: &mut DecodeSource<'_>, root: ElementId,
109	        viewport: Viewport, control: &mut dyn WorkControl) -> Result<()> {
110	        if self.root_display(source, root, control)? { return Err(invalid(0)); }
111	        crate::validate::viewport(viewport)?;
112	        control.checkpoint().map_err(stopped)?;
113	        self.scenes[0].viewport = Some(viewport);
114	        self.initialization = DecodeInitialization::Traversing;
115	        Ok(())
116	    }
117	    /// Called only after original attribute/style/display validation establishes
118	    /// root display:none. Transform/viewport parsing and descendants are skipped.
119	    pub fn initialize_hidden_root(&mut self, source: &mut DecodeSource<'_>, root: ElementId,
120	        control: &mut dyn WorkControl) -> Result<()> {
121	        if !self.root_display(source, root, control)? { return Err(invalid(0)); }
122	        self.require_empty_hidden()?;
123	        control.checkpoint().map_err(stopped)?;
124	        self.initialization = DecodeInitialization::Hidden;
125	        Ok(())
126	    }
127	    fn require_empty_hidden(&self) -> Result<()> {
128	        if self.scenes.len() != 1 || self.scenes[0].lengths().iter().any(|n| *n != 0)
129	            || !self.scenes[0].publications.is_empty() || self.draft_depth != 0
130	            || self.request.is_some() || self.text_commands != 0 {
131	            return Err(invalid(0));
132	        }
133	        Ok(())
134	    }
135	    /// Admit the actual late parser result after successful traversal/root_seen.
136	    /// No replacement is allowed. Admission counts source once and all actual
137	    /// animation capacities, including nested spare capacity. Failed admission
138	    /// leaves initialization and all scene identities intact and returns input.
139	    /// Active drafts/requests survive installation so finalized child renders can
140	    /// finish deferred publication. Freeze still rejects every pending scope.
141	    pub fn finalize_decode(&mut self, animation: OwnedAnimation, generation: u64,
142	        control: &mut dyn WorkControl) -> std::result::Result<(), FinalizationError> {
143	        let result = (|| {
144	            control.checkpoint().map_err(stopped)?;
145	            if self.animation.parsed().is_some() || generation != self.generation
146	                || !matches!(self.initialization, DecodeInitialization::Traversing | DecodeInitialization::Hidden)
147	                || !std::sync::Arc::ptr_eq(&self.source, animation.source_owner()) {
148	                return Err(invalid(0));
149	            }
150	            if self.initialization == DecodeInitialization::Hidden { self.require_empty_hidden()?; }
151	            // storage_bytes performs fixed arithmetic per track; poll at each
152	            // actual retained track before that bounded measurement, not per key.
153	            for _ in animation.tracks() {
154	                control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
155	            }
156	            let owned = animation.storage_bytes().ok_or_else(arithmetic)?;
157	            let incoming = owned.checked_sub(self.source.capacity()).ok_or_else(arithmetic)?;
158	            let live = add(self.stats.live_bytes, incoming)?;
159	            let history = add(self.stats.total_allocated_bytes, incoming)?;
160	            let count = self.stats.allocation_count.checked_add(usize::from(incoming != 0))
161	                .ok_or_else(arithmetic)?;
162	            if live > self.limits.reserved_bytes { return Err(limit(LimitKind::ReservedBytes)); }
163	            control.checkpoint().map_err(stopped)?;
164	            self.stats.live_bytes = live;
165	            self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(live);
166	            self.stats.total_allocated_bytes = history;
167	            self.stats.allocation_count = count;
168	            Ok(())
169	        })();
170	        if let Err(diagnostic) = result { return Err(FinalizationError { diagnostic, animation }); }
171	        self.animation = AnimationStorage::Parsed(animation);
172	        if self.initialization == DecodeInitialization::Traversing {
173	            self.initialization = DecodeInitialization::Finalized;
174	        } else {
175	            self.initialization = DecodeInitialization::HiddenFinalized;
176	        }
177	        Ok(())
178	    }
179	    /// Complete decode with an explicit hidden result; ordinary freeze never
180	    /// publishes a drawable graph without a positive validated viewport.
181	    pub fn freeze_decode(mut self, control: &mut dyn WorkControl) -> Result<DecodedScene> {
182	        if !matches!(self.initialization, DecodeInitialization::Hidden | DecodeInitialization::HiddenFinalized) {
183	            return self.freeze_controlled(control).map(DecodedScene::Drawable);
184	        }
185	        control.checkpoint().map_err(stopped)?;
186	        self.require_empty_hidden()?;
187	        let animation = self.animation.parsed().ok_or_else(|| invalid(0))?;
188	        let measured = add(animation.storage_bytes().ok_or_else(arithmetic)?,
189	            crate::memory::bytes(&self.scenes)?)?;
190	        let measured = add(measured, self.scenes[0].storage_bytes_controlled(control)?)?;
191	        if measured != self.stats.live_bytes || measured > self.limits.reserved_bytes {
192	            return Err(invalid(0));
193	        }
194	        control.checkpoint().map_err(stopped)?;
195	        self.scenes[0].sealed = true;
196	        Ok(DecodedScene::Hidden(HiddenScene { storage: self }))
197	    }
198	}
