 44	macro_rules! room {
 45	    ($self:ident,$index:expr,$field:ident,$extra:expr,$cap:expr,$pending:expr) => {{
 46	        let pending = $pending;
 47	        let current = add($self.stats.live_bytes, pending)?;
 48	        let available = $self
 49	            .limits
 50	            .reserved_bytes
 51	            .checked_sub(current)
 52	            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
 53	        // Check all counters before the mutating reserve can transfer old values.
 54	        let history_room = usize::MAX - $self.stats.total_allocated_bytes;
 55	        let available = available.min(history_room);
 56	        if $self.stats.allocation_count == usize::MAX {
 57	            return Err(arithmetic());
 58	        }
 59	        let (new, old) = reserve(&mut $self.scenes[$index].$field, $extra, $cap, available)?;
 60	        if new != 0 {
 61	            $self.stats.peak_live_bytes = $self.stats.peak_live_bytes.max(add(current, new)?);
 62	            $self.stats.total_allocated_bytes = add($self.stats.total_allocated_bytes, new)?;
 63	            $self.stats.allocation_count += 1;
 64	            $self.stats.live_bytes = add($self.stats.live_bytes - old, new)?;
 65	        }
 66	    }};
 67	}
