 27	fn parsed(d: &LexicalDocument) -> ShapeInput {
 28	    let source = d.source();
 29	    let start = source.windows(4).position(|b| b == b" d=\"").unwrap() + 4;
 30	    let end = start + source[start..].iter().position(|b| *b == b'"').unwrap();
 31	    let element_start = source.windows(5).position(|b| b == b"<path").unwrap();
 32	    let element_end = end + 3;
 33	    let path = vexel_svg_path::parse_path(source, Span { start, end }, identity(), Default::default()).unwrap();
 34	    ShapeInput { edge_colors: vec![[1, 2, 3, 255]; path.edges.len()], path,
 35	        shape: Shape::new(SourceMap { element: Span { start: element_start, end: element_end },
 36	            transform: identity(), transform_node: None }) }
 37	}
 38	fn finish(b: &mut SceneBuilder, d: &LexicalDocument) {
 39	    let actual = parse_owned_controlled(d.source_owner(), d.tokens(), &mut Run).unwrap();
 40	    b.finalize_decode(actual, 7, &mut Run).unwrap();
 41	}
