228	    assert!(Arc::ptr_eq(failure.animation.source_owner(), d.source_owner()));
229	    assert!(b.freeze().is_err()); // explicit abort by Drop, no false completed graph
230	    drop(failure);
231	    // Exact actual-capacity envelope admits once, without source double charge.
232	    limits.reserved_bytes = base + extra;
