 13	/// Canonical lexical planning/target anchor in the same active scene/draft/source.
 14	/// Its element may differ from the separately resolved definition being planned.
 15	#[derive(Debug, Clone, Copy)]
 16	pub struct DefinitionOwner {
 17	    scene: SceneId,
 18	    draft: u64,
 19	    generation: u64,
 20	    target: DefinitionTarget,
 21	    element: ElementId,
 22	}
 23	impl DefinitionOwner {
 24	    pub(crate) fn matches_draft(self, draft: &DraftToken, generation: u64) -> bool {
 25	        self.scene == draft.mark.scene && self.draft == draft.nonce && self.generation == generation
 26	    }
 27	    pub fn target(self) -> DefinitionTarget {
 28	        self.target
 29	    }
 30	    pub fn element(self) -> ElementId {
 31	        self.element
 32	    }
 33	    pub fn validate(self, ctx: &DefinitionContext<'_, '_>) -> Result<()> {
 34	        ctx.validate()?;
 35	        let active = ctx.builder.active_draft().ok_or_else(|| invalid(0))?;
 36	        if ctx.scene != self.scene
 37	            || active.scene != self.scene
 38	            || active.nonce != self.draft
 39	            || ctx.builder.generation != self.generation
 40	        {
 41	            return Err(invalid(0));
 42	        }
 43	        let view = ctx.builder.traversal_scene(self.scene)?;
 44	        match self.target {
 45	            DefinitionTarget::Shape(id) if view.shape(id).is_some() => Ok(()),
 46	            DefinitionTarget::Group(id) if view.group(id).is_some() => Ok(()),
 47	            _ => Err(invalid(0)),
 48	        }
 49	    }
 50	}
 51	impl SceneBuilder {
 52	    pub fn definition_owner(
 53	        &self,
 54	        draft: &DraftToken,
 55	        source: &DecodeSource<'_>,
 56	        element: ElementId,
 57	        target: DefinitionTarget,
 58	        control: &mut dyn WorkControl,
 59	    ) -> Result<DefinitionOwner> {
 60	        self.draft_index(draft)?;
 61	        if !std::sync::Arc::ptr_eq(self.source_owner(), source.source_owner()) {
 62	            return Err(invalid(0));
 63	        }
 64	        source.element(element, crate::memory::add(element.0, 1)?, control)?;
 65	        let view = self.traversal_scene(draft.mark.scene)?;
 66	        match target {
 67	            DefinitionTarget::Shape(id) if view.shape(id).is_some() => {}
 68	            DefinitionTarget::Group(id) if view.group(id).is_some() => {}
 69	            _ => return Err(invalid(0)),
 70	        }
 71	        Ok(DefinitionOwner {
 72	            scene: draft.mark.scene,
 73	            draft: draft.nonce,
 74	            generation: self.generation,
 75	            target,
 76	            element,
 77	        })
 78	    }
 79	    /// Atomic owning filter publication on a real (possibly empty) group. The
 80	    /// child range is finalized later using the same guarded draft mutator.
 81	    pub fn publish_group_filter(
 82	        &mut self,
 83	        draft: &DraftToken,
 84	        owner: DefinitionOwner,
 85	        filter: Filter,
 86	        primitives: &[FilterPrimitive],
 87	        control: &mut dyn WorkControl,
 88	    ) -> Result<FilterId> {
 89	        let i = self.draft_index(draft)?;
 90	        if owner.scene != draft.mark.scene
 91	            || owner.draft != draft.nonce
 92	            || owner.generation != self.generation
 93	        {
 94	            return Err(invalid(0));
 95	        }
 96	        let DefinitionTarget::Group(group) = owner.target else {
 97	            return Err(invalid(0));
 98	        };
 99	        self.draft_slot(draft, 9, group.index(), self.scenes[i].groups.len())?;
100	        let mut value = *self
101	            .traversal_scene(owner.scene)?
102	            .group(group)
103	            .ok_or_else(|| invalid(0))?;
104	        let mut mark = self.checkpoint_internal(owner.scene)?;
105	        let result = (|| {
106	            let id = self.append_filter(owner.scene, filter, primitives, control)?;
107	            value.filter = Some(id);
108	            self.finalize_group(draft, group, value, control)?;
109	            Ok(id)
110	        })();
111	        if result.is_err() {
112	            mark.epoch = self.scenes[i].epoch;
113	            self.rollback_internal(mark)?;
114	        }
115	        result
116	    }
117	}
