181	/// Actual shared resolve+publication operation; resolver output is used directly.
182	pub fn resolve_publish_cached(
183	    resolver: &mut dyn CachedPaintResolver,
184	    source: &mut DecodeSource<'_>,
185	    ledger: &mut ChargeLedger,
186	    builder: &mut SceneBuilder,
187	    scene: SceneId,
188	    value: XmlSpan,
189	    edges: &[Edge],
190	    inverse: Affine,
191	    viewport: [f64; 2],
192	    channel: PaintChannel,
193	    control: &mut dyn WorkControl,
194	) -> Result<usize> {
195	    ledger.require_owner(ledger.owner_identity(), source.source_owner())?;
196	    if !std::sync::Arc::ptr_eq(builder.source_owner(), source.source_owner()) {
197	        return Err(invalid(0));
198	    }
199	    builder.writable(scene)?;
200	    if value.slice(source.source()).is_none() {
201	        return Err(invalid(value.offset));
202	    }
203	    control.checkpoint().map_err(stopped)?;
204	    let cached =
205	        resolver.resolve_cached(source, ledger, value, edges, inverse, viewport, control)?;
206	    builder.append_cached_paint(scene, cached, channel, control)
207	}
