 20	    pub fn begin_draft(&mut self, scene: SceneId) -> Result<DraftToken> {
 21	        let i = self.index(scene)?;
 22	        if matches!(self.initialization, DecodeInitialization::Unresolved | DecodeInitialization::Hidden | DecodeInitialization::HiddenFinalized) { return Err(invalid(0)); }
 23	        if self.scenes[i].sealed || self.draft_depth >= 64 || self.request_protects_scene(scene) {
 24	            return Err(invalid(0));
 25	        }
 26	        if let Some(parent) = self.active_draft() {
 27	            if scene.index() < parent.scene_count {
 28	                return Err(invalid(0));
 29	            }
 30	        }
 31	        let nonce = self.serial()?;
 32	        let mark = self.checkpoint_unrestricted(scene)?;
 33	        let scene_count = self.scenes.len();
 34	        self.drafts[self.draft_depth] = Some(ActiveDraft {
 35	            scene,
 36	            nonce,
 37	            scene_count,
 38	        });
 39	        self.draft_depth += 1;
 40	        Ok(DraftToken {
 41	            mark,
 42	            nonce,
 43	            scene_count,
 44	            ignored: self.ignored,
 45	            text_commands: self.text_commands,
 46	        })
 47	    }
 48	    pub(crate) fn active_draft(&self) -> Option<ActiveDraft> {
 49	        self.draft_depth.checked_sub(1).and_then(|i| self.drafts[i])
 50	    }
 51	    pub(crate) fn draft_index(&self, token: &DraftToken) -> Result<usize> {
 52	        let active = self.active_draft().ok_or_else(|| invalid(0))?;
 53	        if active.scene != token.mark.scene
 54	            || active.nonce != token.nonce
 55	            || active.scene_count != token.scene_count
 56	        {
 57	            return Err(invalid(0));
 58	        }
 59	        let i = self.index(active.scene)?;
 60	        if self.scenes[i].sealed {
 61	            return Err(invalid(0));
 62	        }
 63	        if self.scenes[i]
 64	            .lengths()
 65	            .iter()
 66	            .zip(token.mark.lengths)
 67	            .any(|(now, then)| *now < then)
 68	        {
 69	            return Err(invalid(0));
 70	        }
 71	        Ok(i)
 72	    }
 73	    pub(crate) fn draft_slot(
 74	        &self,
 75	        token: &DraftToken,
 76	        table: usize,
 77	        slot: usize,
 78	        len: usize,
 79	    ) -> Result<usize> {
 80	        let i = self.draft_index(token)?;
 81	        let first = self
 82	            .request
 83	            .as_ref()
 84	            .map_or(token.mark.lengths[table], |r| {
 85	                if r.mark.scene == token.mark.scene {
 86	                    r.mark.lengths[table].max(token.mark.lengths[table])
 87	                } else {
 88	                    token.mark.lengths[table]
 89	                }
 90	            });
 91	        if slot < first || slot >= len {
 92	            return Err(invalid(0));
 93	        }
 94	        Ok(i)
 95	    }
 96	    /// Validation failure/cancellation leaves the token active and rollbackable.
 97	    pub fn commit_draft(
 98	        &mut self,
 99	        token: &DraftToken,
100	        control: &mut dyn WorkControl,
101	    ) -> Result<()> {
102	        self.draft_index(token)?;
103	        if self.request_protects_draft(token) {
