112	    /// Rollback includes all descendants created after this graph checkpoint.
113	    /// Cleanup is unconditional even when the caller's work control has stopped.
114	    pub fn rollback_draft(&mut self, mut token: DraftToken) -> Result<()> {
115	        if self.request_protects_draft(&token) {
116	            return Err(invalid(0));
117	        }
118	        let i = self.draft_index(&token)?;
119	        let mut released = 0;
120	        for scene in &self.scenes[token.scene_count..] {
121	            released = crate::memory::add(released, scene.storage_bytes()?)?;
122	        }
123	        token.mark.epoch = self.scenes[i].epoch;
124	        self.rollback_internal(token.mark)?;
125	        self.scenes.truncate(token.scene_count);
126	        self.stats.live_bytes -= released;
127	        self.ignored = token.ignored;
128	        self.text_commands = token.text_commands;
129	        self.draft_depth -= 1;
130	        self.drafts[self.draft_depth] = None;
131	        Ok(())
132	    }
