232	    pub(crate) fn rollback_internal(&mut self, mark: BuildMark) -> Result<()> {
233	        let i = self.writable(mark.scene)?;
234	        let scene = &self.scenes[i];
235	        if scene.publications.len() < mark.publications
236	            || scene.epoch != mark.epoch
237	            || scene
238	                .lengths()
239	                .iter()
240	                .zip(mark.lengths)
241	                .any(|(now, then)| *now < then)
242	        {
243	            return Err(invalid(0));
244	        }
245	        let epoch = scene.epoch.checked_add(1).ok_or_else(arithmetic)?;
246	        let before = scene.storage_bytes()?;
247	        self.scenes[i].truncate(mark.lengths);
248	        self.scenes[i]
249	            .publications
250	            .retain(|p| p.order < mark.publications);
251	        self.scenes[i].epoch = epoch;
252	        self.scenes[i].image_pixels = mark.image_pixels;
253	        let after = self.scenes[i].storage_bytes()?;
254	        self.stats.live_bytes = self.stats.live_bytes - (before - after);
255	        Ok(())
256	    }
